// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(uint256 blockNumber, uint256 timestamp, uint256 senderSeed) public {
        blockNumber = bound(blockNumber, 1, type(uint256).max - 15);
        timestamp = bound(timestamp, 1, type(uint256).max - 1);
        address sender = address(uint160(uint256(keccak256(abi.encode(senderSeed)))));
        vm.assume(sender != address(0));

        vm.roll(blockNumber);
        vm.warp(timestamp);

        vm.deal(sender, 20 ether);

        uint256 balanceBefore = address(c).balance;

        vm.prank(sender);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        require(ok, "fallback reverted");

        if (blockNumber % 15 == 0) {
            assertEq(address(c).balance, 0 ether, "Contract balance must be 0 after transfer");
        }
    }
}
